#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <cstdint>
#include <cstdlib>
#include <backends/cxxrtl/cxxrtl_vcd.h>

using namespace cxxrtl_design;

// Load word-addressed hex file into CXXRTL memory
template<typename M>
bool load_hex(M &mem, size_t depth, const std::string &path) {
    std::ifstream f(path);
    if (!f.is_open()) return false;
    std::string line;
    size_t addr = 0;
    while (std::getline(f, line) && addr < depth) {
        if (line.empty() || line[0] == '/' || line[0] == '#') continue;
        if (line[0] == '@') {
            addr = std::stoul(line.substr(1), nullptr, 16);
            continue;
        }
        uint32_t val = std::stoul(line, nullptr, 16);
        mem[addr].template set<uint32_t>(val);
        addr++;
    }
    return true;
}

int main(int argc, char **argv) {
    p_riscv32i__complete top;

    uint32_t pass_addr = 0xFFFFFFFF;
    uint32_t fail_addr = 0xFFFFFFFE;
    std::string vcd_file;
    std::string hex_file;
    int timeout = 10000;

    for (int i = 1; i < argc; i++) {
        std::string arg = argv[i];
        if (arg.substr(0, 11) == "+pass_addr=") pass_addr = std::stoul(arg.substr(11), nullptr, 16);
        else if (arg.substr(0, 11) == "+fail_addr=") fail_addr = std::stoul(arg.substr(11), nullptr, 16);
        else if (arg.substr(0, 5) == "+vcd=") vcd_file = arg.substr(5);
        else if (arg.substr(0, 5) == "+hex=") hex_file = arg.substr(5);
        else if (arg.substr(0, 9) == "+timeout=") timeout = std::stoi(arg.substr(9));
    }

    // Load rf memory (32 x 32-bit)
    load_hex(top.memory_p_rf, 32, "rf.hex");
    // Load umem memory (8192 x 32-bit)
    if (!hex_file.empty()) {
        if (!load_hex(top.memory_p_umem, 8192, hex_file))
            std::cerr << "Warning: could not load " << hex_file << std::endl;
    } else {
        load_hex(top.memory_p_umem, 8192, "umem.hex");
    }

    cxxrtl::vcd_writer vcd;
    if (!vcd_file.empty()) {
        cxxrtl::debug_items di;
        top.debug_info(di, "");
        vcd.timescale(1, "ns");
        vcd.add(di);
    }

    // Reset
    top.p_reset.set<bool>(true);
    top.p_reset__pc__rd.set<uint32_t>(0);
    for (int i = 0; i < 3; i++) {
        top.p_clk.set<bool>(false);
        top.step();
        if (!vcd_file.empty()) vcd.sample(i*2);
        top.p_clk.set<bool>(true);
        top.step();
        if (!vcd_file.empty()) vcd.sample(i*2+1);
    }
    top.p_reset.set<bool>(false);

    // Run simulation
    for (int cycle = 0; cycle < timeout; cycle++) {
        top.p_clk.set<bool>(false);
        top.step();
        if (!vcd_file.empty()) vcd.sample(6 + cycle*2);
        top.p_clk.set<bool>(true);
        top.step();
        if (!vcd_file.empty()) vcd.sample(6 + cycle*2+1);

        uint32_t pc = top.p_pc__rd.get<uint32_t>();
        if (pc == pass_addr) {
            std::cout << "TEST PASSED" << std::endl;
            goto done;
        }
        if (pc == fail_addr) {
            std::cout << "TEST FAILED at pc=0x" << std::hex << pc << std::endl;
            goto done;
        }
    }
    std::cout << "TIMEOUT" << std::endl;

done:
    if (!vcd_file.empty()) {
        std::ofstream vf(vcd_file);
        vf << vcd.buffer;
    }
    return 0;
}
